-- Final Side Pool boundary repairs. Elections/configuration lock at play start;
-- already-posted payouts remain recordable through results/finalization.
create or replace function app.guard_side_pool_election_start_v4() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if app.event_play_state_v1(new.event_id) in('in_progress','completed','finalized') or exists(select 1 from app.event_side_pool_reconciliations where pool_id=new.pool_id) then raise exception 'side_pool_election_locked'; end if;
 return new;
end $$;
drop trigger if exists event_side_pool_election_start_guard on app.event_side_pool_election_versions;
create trigger event_side_pool_election_start_guard before insert on app.event_side_pool_election_versions for each row execute function app.guard_side_pool_election_start_v4();
drop trigger if exists event_side_pool_team_election_guard on app.event_side_pool_team_election_versions;
create trigger event_side_pool_team_election_guard before insert on app.event_side_pool_team_election_versions for each row execute function app.guard_side_pool_election_start_v4();

create or replace function app.guard_side_pool_team_election_v3() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if not exists(select 1 from app.tournament_roles where tournament_id=new.tournament_id and profile_id=new.actor_profile_id and role in('director','co_director')) then raise exception 'side_pool_not_director'; end if;
 if app.event_play_state_v1(new.event_id) in('in_progress','completed','finalized') or exists(select 1 from app.event_side_pool_reconciliations where pool_id=new.pool_id) then raise exception 'side_pool_finalized'; end if;
 if exists(select 1 from app.event_side_pool_team_election_versions where election_id=new.election_id and team_entry_id=new.team_entry_id and version>=new.version) then raise exception 'election_id_conflict'; end if;
 return new;
end $$;

-- Replace both payout RPCs so payout timing is allowed after play and current
-- eligibility/identity are checked before an immutable correction is appended.
create or replace function public.set_event_side_pool_payout_v1(p_actor_id uuid,p_tournament_id uuid,p_event_id uuid,p_pool_id uuid,p_participant_id uuid,p_payout_id uuid,p_placement integer,p_amount_minor integer,p_voided boolean,p_reason text,p_idempotency_key uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare h text; prior app.operation_receipts%rowtype; rid uuid:=extensions.gen_random_uuid(); v integer; response jsonb;
begin
 if p_actor_id is null or p_payout_id is null or p_idempotency_key is null or p_placement<1 or p_amount_minor<0 or p_voided is null or length(trim(p_reason)) not between 1 and 500 then return jsonb_build_object('status','rejected','code','invalid_request'); end if;
 h:=encode(extensions.digest(convert_to(jsonb_build_array('set_event_side_pool_payout_v1',p_actor_id,p_tournament_id,p_event_id,p_pool_id,p_participant_id,p_payout_id,p_placement,p_amount_minor,p_voided,p_reason)::text,'utf8'),'sha256'),'hex'); select * into prior from app.operation_receipts where actor_profile_id=p_actor_id and client_operation_id=p_idempotency_key; if found then if prior.request_hash<>h then return jsonb_build_object('status','rejected','code','idempotency_conflict'); end if; return prior.response_payload; end if;
 if not exists(select 1 from app.tournament_roles where tournament_id=p_tournament_id and profile_id=p_actor_id and role in('director','co_director')) then return jsonb_build_object('status','rejected','code','not_director'); end if;
 if not exists(select 1 from app.event_side_pool_policy_versions where pool_id=p_pool_id and posted_before_play) or not exists(select 1 from app.event_participants where id=p_participant_id and event_id=p_event_id and tournament_id=p_tournament_id) or not exists(select 1 from (select distinct on(participant_id) elected from app.event_side_pool_election_versions where pool_id=p_pool_id and participant_id=p_participant_id order by participant_id,version desc)x where elected) or exists(select 1 from app.event_side_pool_reconciliations where pool_id=p_pool_id) then return jsonb_build_object('status','rejected','code','pool_unavailable'); end if;
 if exists(select 1 from app.event_side_pool_payout_versions where payout_id=p_payout_id and (pool_id<>p_pool_id or event_id<>p_event_id or participant_id<>p_participant_id)) then return jsonb_build_object('status','rejected','code','payout_identity_conflict'); end if;
 select coalesce(max(version),0)+1 into v from app.event_side_pool_payout_versions where payout_id=p_payout_id; response:=jsonb_build_object('status','side_pool_payout_recorded','poolId',p_pool_id,'participantId',p_participant_id,'payoutId',p_payout_id,'version',v,'placement',p_placement,'amountMinor',p_amount_minor,'voided',p_voided); insert into app.operation_receipts(id,actor_profile_id,tournament_id,operation_type,target_id,request_hash,client_operation_id,outcome,response_payload,applied_at) values(rid,p_actor_id,p_tournament_id,'set_event_side_pool_payout_v1',p_payout_id,h,p_idempotency_key,'accepted',response,clock_timestamp()); insert into app.event_side_pool_payout_versions(payout_id,pool_id,tournament_id,event_id,participant_id,version,placement,amount_minor,voided,reason,actor_profile_id,operation_receipt_id) values(p_payout_id,p_pool_id,p_tournament_id,p_event_id,p_participant_id,v,p_placement,p_amount_minor,p_voided,trim(p_reason),p_actor_id,rid); insert into app.audit_events(tournament_id,actor_profile_id,operation_receipt_id,entity_type,entity_id,action,after_state) values(p_tournament_id,p_actor_id,rid,'side_pool_payout',p_payout_id,case when p_voided then 'side_pool_payout_voided' else 'side_pool_payout_recorded' end,response); return response;
end $$;
revoke all on function public.set_event_side_pool_payout_v1(uuid,uuid,uuid,uuid,uuid,uuid,integer,integer,boolean,text,uuid) from public,anon,authenticated; grant execute on function public.set_event_side_pool_payout_v1(uuid,uuid,uuid,uuid,uuid,uuid,integer,integer,boolean,text,uuid) to service_role;

create or replace function public.set_event_side_pool_team_payout_v1(p_actor_id uuid,p_tournament_id uuid,p_event_id uuid,p_pool_id uuid,p_team_entry_id uuid,p_payout_id uuid,p_placement integer,p_amount_minor integer,p_voided boolean,p_reason text,p_idempotency_key uuid) returns jsonb language plpgsql security definer set search_path='' as $$
