begin
 if p_payout_id is null or p_idempotency_key is null or p_placement<1 or p_amount_minor<0 or p_voided is null or length(trim(p_reason)) not between 1 and 500 then return jsonb_build_object('status','rejected','code','invalid_request'); end if;
 h:=encode(extensions.digest(convert_to(jsonb_build_array('set_event_side_pool_team_payout_v1',p_actor_id,p_tournament_id,p_event_id,p_pool_id,p_team_entry_id,p_payout_id,p_placement,p_amount_minor,p_voided,p_reason)::text,'utf8'),'sha256'),'hex'); select * into prior from app.operation_receipts where actor_profile_id=p_actor_id and client_operation_id=p_idempotency_key; if found then if prior.request_hash<>h then return jsonb_build_object('status','rejected','code','idempotency_conflict'); end if; return prior.response_payload; end if;
 if not exists(select 1 from app.tournament_roles where tournament_id=p_tournament_id and profile_id=p_actor_id and role in('director','co_director')) then return jsonb_build_object('status','rejected','code','not_director'); end if;
 if not exists(select 1 from app.event_side_pool_policy_versions where pool_id=p_pool_id and posted_before_play) or not exists(select 1 from app.event_team_entries where id=p_team_entry_id and event_id=p_event_id and tournament_id=p_tournament_id) or not exists(select 1 from (select distinct on(team_entry_id) elected from app.event_side_pool_team_election_versions where pool_id=p_pool_id and team_entry_id=p_team_entry_id order by team_entry_id,version desc)x where elected) or exists(select 1 from app.event_side_pool_reconciliations where pool_id=p_pool_id) then return jsonb_build_object('status','rejected','code','pool_unavailable'); end if;
 if exists(select 1 from app.event_side_pool_team_payout_versions where payout_id=p_payout_id and (pool_id<>p_pool_id or event_id<>p_event_id or team_entry_id<>p_team_entry_id)) then return jsonb_build_object('status','rejected','code','payout_identity_conflict'); end if;
 select coalesce(max(version),0)+1 into v from app.event_side_pool_team_payout_versions where payout_id=p_payout_id; response:=jsonb_build_object('status','side_pool_team_payout_recorded','poolId',p_pool_id,'teamEntryId',p_team_entry_id,'payoutId',p_payout_id,'version',v,'amountMinor',p_amount_minor,'voided',p_voided); insert into app.operation_receipts(id,actor_profile_id,tournament_id,operation_type,target_id,request_hash,client_operation_id,outcome,response_payload,applied_at) values(rid,p_actor_id,p_tournament_id,'set_event_side_pool_team_payout_v1',p_payout_id,h,p_idempotency_key,'accepted',response,clock_timestamp()); insert into app.event_side_pool_team_payout_versions(payout_id,pool_id,tournament_id,event_id,team_entry_id,version,placement,amount_minor,voided,reason,actor_profile_id,operation_receipt_id) values(p_payout_id,p_pool_id,p_tournament_id,p_event_id,p_team_entry_id,v,p_placement,p_amount_minor,p_voided,trim(p_reason),p_actor_id,rid); insert into app.audit_events(tournament_id,actor_profile_id,operation_receipt_id,entity_type,entity_id,action,after_state) values(p_tournament_id,p_actor_id,rid,'side_pool_team_payout',p_payout_id,case when p_voided then 'side_pool_team_payout_voided' else 'side_pool_team_payout_recorded' end,response); return response;
end $$;
revoke all on function public.set_event_side_pool_team_payout_v1(uuid,uuid,uuid,uuid,uuid,uuid,integer,integer,boolean,text,uuid) from public,anon,authenticated; grant execute on function public.set_event_side_pool_team_payout_v1(uuid,uuid,uuid,uuid,uuid,uuid,integer,integer,boolean,text,uuid) to service_role;
